# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMT5-000001",
    "name": "Somchai สมชาย",
    "kind": "first-name",
    "meaning": "Somchai (สมชาย) is a masculine given name in Thai. Meaning: Worthy man. Som (worthy) + chai (man)."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Som")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

